def clean(df):
    df = df.copy()
    # drop exact duplicate rows
    df = df.drop_duplicates()
    # normalize Category labels: trim, fix case variants and the 'Furnture' typo
    def fix_cat(v):
        if pd.isna(v):
            return v
        s = str(v).strip()
        low = s.lower()
        if low in ('furnture', 'furniture'):
            return 'Furniture'
        if low == 'electronics':
            return 'Electronics'
        if low == 'accessories':
            return 'Accessories'
        if low == 'office supplies':
            return 'Office Supplies'
        return s
    df['Category'] = df['Category'].apply(fix_cat)
    # parse dates (invalid ones become NaT) - not needed for the question but keeps data consistent
    df['Date'] = pd.to_datetime(df['Date'], format='%Y-%m-%d', errors='coerce')
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Category'])
    counts = d.groupby('Category').size()
    return {str(k): int(v) for k, v in counts.items()}
